/**
 * tiny控件国际化处理文件，支持通过浏览器cookie或是window全局变量来存放国际化标识
 */
define('i18n/internationalization',["i18n/en-US/widgetsLanguage", "i18n/zh-CN/widgetsLanguage"], function(enLanguage, zhLanguage) {

    var language_key = "tiny_language";
    window.tinyLanguage = {};

    /**
     * 获取tiny控件国际化语言标识，默认返回中文标识
     */
    window.tinyLanguage.getTinyLanguageToken = function() {
        var cookieStr = document.cookie.split("; ");
        var arrLength = cookieStr.length;
        for (var i = 0; i < arrLength; i++) {
            var tempArr = cookieStr[i].split("=");
            if (language_key === tempArr[0]) {
                return tempArr[1];
            }
        }
    }

    /**
     * 添加/重置tiny控件国际化语言标识
     */
    window.tinyLanguage.setTinyLanguageToken = function(token) {
        var cookieString = language_key + "=" + escape(token);
        // 不设定过期时间，浏览器关闭时cookie自动消失
        document.cookie = cookieString;
    }

    /**
     * 根据国际化标识，设置tiny控件语言
     */
    var languageToken = tinyLanguage.getTinyLanguageToken() || window.tinyLanguageToken || "zh";
    if ("en" === languageToken || "en-US" === languageToken) {
        window.tinyLanguage.language = enLanguage;
    } else {
        window.tinyLanguage.language = zhLanguage;
    }


    return window.tinyLanguage;
})
;
