(function() {
  var module = angular.module('tiny.ui.toggleSwitch', ['ng']);

  module.provider('toggleSwitchConfig', [function() {
    this.onLabel = 'ON';
    this.offLabel = 'OFF';
    this.knobLabel = '\u00a0';
    this.height = 18;

    var self = this;
    this.$get = function() {
      return {
        onLabel: self.onLabel,
        offLabel: self.offLabel,
        knobLabel: self.knobLabel,
        height:self.height
      };
    };
  }]);

  module.directive('tinyplusSwitch',['toggleSwitchConfig', function (toggleSwitchConfig) {
    return {
      restrict: 'EA',
      replace: true,
      require:'ngModel',
      scope: {
        disabled: '@',
        onLabel: '@',
        offLabel: '@',
        knobLabel: '@'
      },
      template: '<div role="radio" class="tinyplus-toggle-switch" ng-class="{ \'disabled\': disabled }">' +
          '<div class="tinyplus-toggle-switch-animate" ng-class="{\'tinyplus-switch-off\': !model, \'tinyplus-switch-on\': model}">' +
          '<span class="tinyplus-switch-left" ng-bind="offLabel"></span>' +
          '<span class="tinyplus-knob" ng-bind="knobLabel"></span>' +
          '<span class="tinyplus-switch-right" ng-bind="onLabel"></span>' +
          '</div>' +
          '</div>',
      compile: function(element, attrs) {
        if (!attrs.onLabel) { attrs.onLabel = toggleSwitchConfig.onLabel; }
        if (!attrs.offLabel) { attrs.offLabel = toggleSwitchConfig.offLabel; }
        if (!attrs.knobLabel) { attrs.knobLabel = toggleSwitchConfig.knobLabel; }

        return this.link;
      },
      link: function(scope, element, attrs, ngModelCtrl){
        var KEY_SPACE = 32;
        // �����߶�,����ȡԪ�ظ߶ȷ�Ĭ�ϸ߶ȣ���������Ӧ��ʽ
        var height = element.height();
        if(height && (toggleSwitchConfig.height !== height)) {
            var borderRadius = height/2+"px", lineHeight = height-2 +"px";
            height += "px"; 
            element.find(".tinyplus-toggle-switch-animate").css({"line-height": lineHeight,"border-radius": borderRadius});
            element.find(".tinyplus-switch-left").css({"min-width": height,"border-radius": borderRadius});
            element.find(".tinyplus-switch-right").css({"min-width": height,"border-radius": borderRadius});
        }
        
        element.on('click', function() {
          scope.$apply(scope.toggle);
        });

        element.on('keydown', function(e) {
          var key = e.which ? e.which : e.keyCode;
          if (key === KEY_SPACE) {
            scope.$apply(scope.toggle);
          }
        });

        ngModelCtrl.$formatters.push(function(modelValue){
          return modelValue;
        });

        ngModelCtrl.$parsers.push(function(viewValue){
          return viewValue;
        });

        ngModelCtrl.$viewChangeListeners.push(function() {
          scope.$eval(attrs.ngChange);
        });

        ngModelCtrl.$render = function(){
            scope.model = ngModelCtrl.$viewValue;
        };

        scope.toggle = function toggle() {
          if(!scope.disabled) {
            scope.model = !scope.model;
            ngModelCtrl.$setViewValue(scope.model);
          }
        };
      }
    };
  }]);
})();
define("tiny-lib/angular-toggle-switch", function(){});

