define('tiny-directives/Checkbox',["tiny-directives/Directive", "tiny-widgets/Checkbox"], function(Directive, CheckboxWidget) {

	var DEFAULT_CONFIG = {
		"directiveName" : "tinyCheckbox",
		"widgetClass" : CheckboxWidget,
		"scope" : {
			"id" :"=",
			"iconClass" : "=",
			"text" : "=",
			"width" : "=",
			"height" : "=",
			"checked" : "=",
			"disable" : "=",
			"tooltip" : "=",
			"tipWidth" : "=",
			"click" : "&",
			"change" : "&",
			"value" : "="
		},
		"template" : "<span></span>",
		"replace" : "true",
		"constantProperties" : ["value", "tipWidth"]
	};

	var Checkbox = Directive.extend({
		"init" : function(options) {
			var directiveThis = this;
			directiveThis._super(_.extend({}, DEFAULT_CONFIG, options));
		},
		"compile" : function(){
			var directiveThis = this;
			return directiveThis.link;
		},		
		"link": function( scope, element, attrMap ){
			var checkboxThis = this,constants = _.pick(scope, checkboxThis.constantProperties);
			//filter undefined scope
			var validProperName = [];
			_.filter(constants,function(value,key){
				if(value !== undefined) {
					validProperName.push(key);
				}
                return value !== undefined;
			});
			var checkboxInstance = new checkboxThis.widgetClass(_.pick(constants,validProperName));
			
			checkboxInstance.on("change", function(event){
            	checkboxThis.setAttr(scope, "checked", checkboxInstance.options.checked, attrMap);
            });
            
			element.append(checkboxInstance._element);
			scope.$watch("id", function(newValues, oldValues) {
                checkboxInstance.option("id", newValues);
            });
			scope.$watch("iconClass", function(newValues, oldValues) {
                checkboxInstance.option("icon-class", newValues);
            });
            scope.$watch("text", function(newValues, oldValues) {
                checkboxInstance.option("text", newValues);
            });
            scope.$watch("width", function(newValues, oldValues) {
                checkboxInstance.option("width", newValues);
            });
            scope.$watch("height", function(newValues, oldValues) {
                checkboxInstance.option("height", newValues);
            });
            scope.$watch("checked", function(newValues, oldValues) {
            	if(scope.changeFlag === true) {
                	scope.changeFlag = false;
                	return;
                }
                
                checkboxInstance.option("checked", newValues);
            });
            scope.$watch("disable", function(newValues, oldValues) {
                checkboxInstance.option("disable", newValues);
            });
            scope.$watch("tooltip", function(newValues, oldValues) {
                checkboxInstance.option("tooltip", newValues);
            });
            if (attrMap.click) {
                checkboxInstance._element.on("clickEvt",function(event) {
                    scope.$evalAsync(function(){
                        scope.click({event: event});
                });
                });
            }
            if (attrMap.change) {
                checkboxInstance._element.on("changeEvt", function(event) {
                    scope.$evalAsync(function(){
                        scope.change({event: event});
                    });
                });
            }   
        }
	});
	new Checkbox().toAngularDirective();
	return Checkbox;
});

