        "legendFontColor" : "#666666", //图例文本颜色
        "height" : 180, //高度
        "width" : 500, //宽度
        "shadowImgUrl" : "../themes/default/images/circle_bottom_back.png", //底部阴影图片
        "showShadow" : true, //是否显示底部阴影
