                var countryCode = paras[0] || ''; // 国家代码
                var expNumberType = _.isUndefined(paras[1]) ? 1 : paras[1]; // 期望的电话号码类型，默认mobile
                var isShowDetailError = paras[2]; // 是否展示更详细的错误信息，默认为true
                var checkInfo = {
                    countryCode: countryCode,
                    value: value,
                    validate: validate,
                    expNumberType: expNumberType,
                    isShowDetailError: isShowDetailError
                };
                // 校验输入的电话号码是否符合要求
