                    DTChooserThis._eventPrevent(evt);
                    DTChooserThis._eventStop(evt);
                    DTChooserThis._changeValue('DOWN');
                    DTChooserThis.lastInputTime = DTChooserThis.editorValue;
                    DTChooserThis.focusInput.select();
