            var suggestElement = searchBoxThis.$suggestArea;
            var currSuggestItem = suggestElement.find(".tiny-searchbox-suggest-selected");
            var inputValue;

            currSuggestItem.removeClass("tiny-searchbox-suggest-selected");

            //按键之前不存在已被选中的联想内容
            if (0 == currSuggestItem.length) {
                suggestElement.children().first().addClass("tiny-searchbox-suggest-selected");
                inputValue = suggestElement.find(".tiny-searchbox-suggest-selected").text();
                searchBoxThis.setValue(inputValue);
                return;
            }

            //最后一条联想内容为按键之前已被选中的内容
            if(0 == currSuggestItem.next().length){
                searchBoxThis.setValue(previousInput);
                return;
            }

            currSuggestItem.next().addClass("tiny-searchbox-suggest-selected");
            inputValue = suggestElement.find(".tiny-searchbox-suggest-selected").text();
            searchBoxThis.setValue(inputValue);
