            !_.isUndefined(options.scale) && ( sliderOption.scale = options.scale) ;
            !_.isUndefined(options.smooth) && ( sliderOption.smooth = options.smooth) ;
            !_.isUndefined(options.limits) && ( sliderOption.limits = options.limits) ;
