define('tiny-widgets/Switch',["tiny-lib/angular", "tiny-lib/jquery", "tiny-lib/Class", "tiny-widgets/Widget", "tiny-lib/underscore", "tiny-common/util", "tiny-lib/encoder"],
function(angular, $, Class, Widget, _, util, encoder) {

    var HEMICYCLE_WIDTH = 10;
    var DEFAULT_CONFIG = {
        template : '<div class="tiny-switch">' +                            
                                '<div class="tiny-switch-box">' +
                                    '<div class="switch-button-bg">' +
                                        '<div class="tiny-switch-left"></div>' +
                                        '<div class="tiny-switch-middle"></div>' +
                                        '<div class="tiny-switch-right"></div>' +
                                    '</div>' +
                                '</div>' +
                            '</div>',
        display : true,        
        disable : false,
        items : [{value: "off"}, {value: "on"}],
        selected: "off",
        standard : true
    };

    var widgetsLanguage;
    var Switch = Widget.extend({

        init : function(options) {
            var widgetThis = this;
            widgetsLanguage = tinyLanguage.language;
            DEFAULT_CONFIG.items[0].label = widgetsLanguage.off;
            DEFAULT_CONFIG.items[1].label = widgetsLanguage.on;
            widgetThis._super(_.extend({}, DEFAULT_CONFIG, options));             
            
            var _parentDiv = $("#" + options["id"]);                    
            if( _parentDiv.length > 0 ) {
                _parentDiv.append(widgetThis._element); 
                widgetThis._update();
            } else {                
                widgetThis._element.attr("id", widgetThis.options.id);
            }            
        },    

        _setSelectedItem : function(value) {            
            var widgetThis = this;
            var item = _.find( widgetThis.options.items, function(item){ return item.value == value; });
            if ( item ) {
                widgetThis.options.selected = value;                
                widgetThis.selectedItem = item;
                widgetThis._update();
            }
        },

        _setOption : function(key, value) {
            var widgetThis = this;
            widgetThis._super(key, value);
            switch(key) {                
                case "display":
                    widgetThis._setDisplay(value);
                    break;               
                case "disable" : 
                    widgetThis._setDisable(value);
                    break;
                case "selected" : 
                    widgetThis._setSelectedItem(value);
                    break;                
                case "adjust" : 
                    widgetThis._update();                    
                    break;
                default:
                    break;
            }
        },
        
        _addBehavior : function() {
            var widgetThis = this;
            var options = widgetThis.options;
            var param, newValue;

            if (options.standard) {
                widgetThis._element.find(".tiny-switch-box > div").on("click", function(evt) {
                    if (options.disable) {
                        return;
                    }
                    newValue = _.find(options.items, function(item){ return item.value != options.selected; });                    
                    param = {oldValue: options.selected, newValue : newValue.value};
                    if (options.isDirective) {
                        widgetThis.trigger( "changeEvt", [param] );
                    } else {
                        if ("function" === ( typeof options.change)) {
                            var canChange = options.change( param );
                            if (util.isFalse(canChange)) {
                                  return;
                            }                            
                        }
                        widgetThis._setSelectedItem( newValue.value ); 
                    }                                                                    
                });
            } else {
                widgetThis._element.find(".switch-button").on("click", function(evt) {   
                    var $currButton = $(evt.currentTarget);                 
                    if (options.disable || $currButton.hasClass("switch-button-selected")) {
                        return;
                    }
                    var value = $currButton.attr("value");
                    newValue = _.find(widgetThis.options.items, function(item){ return item.value == value; });
                    param = {oldValue: options.selected, newValue : newValue.value};
                    if (options.isDirective) {
                        widgetThis.trigger( "changeEvt", [param] );
                    } else {
                        if ("function" === ( typeof options.change)) {                        
                            var canChange = options.change( param );
                            if (util.isFalse(canChange)) {
                                return;
                            }                            
                        }
                        widgetThis._setSelectedItem( newValue.value ); 
                    }                    
                });
            }

        },

        _generateElement : function() {
            var widgetThis = this;
            widgetThis._super();
            var $html = widgetThis._element;
            var $box = $html.find(".tiny-switch-box");
            var _buttonTemplate = 
                '<div class="{0}" {1}>'+
                        '<div class="tiny-switch-left"></div>'+
                        '<div class="tiny-switch-middle">{2}</div>'+
                        '<div class="tiny-switch-right"></div>'+
                '</div>';

            widgetThis.selectedItem = _.find( widgetThis.options.items, function(item){ return item.value == widgetThis.options.selected; });
            if ( widgetThis.options.standard ) {               
                $box.append(_buttonTemplate.replace("{0}", "switch-button-off").replace("{1}", "").replace("{2}", $.encoder.encodeForHTML(widgetThis.options.items[0].label)));
            } else {
                _.each(widgetThis.options.items, function( item ) {
                    $box.append(_buttonTemplate.replace("{0}", "switch-button").replace("{1}", $.encoder.encodeForHTMLAttribute("value", ""+item.value)).replace("{2}", $.encoder.encodeForHTML(item.label)));
                });
            }
            return $html;
        },
        
        _setDisplay : function( display ) {
            var widgetThis = this;
            widgetThis.options.display = display;
            display ? widgetThis._element.show() : widgetThis._element.hide();
        },

        _setDisable : function( disabled ) {
            var widgetThis = this;
            widgetThis.options.disable = disabled;
            if ( disabled ) {
                widgetThis._element.removeClass("tiny-switch");
                widgetThis._element.addClass("tiny-switch-disabled");
            } else {
                widgetThis._element.removeClass("tiny-switch-disabled");
                widgetThis._element.addClass("tiny-switch");
            }            
        },
        
        _update : function() {
            var widgetThis = this;
            widgetThis.options.standard ? widgetThis._updateStandard() : widgetThis._updateExtend();            
        },

        /**
         * 更新标准开关
        */
        _updateStandard : function() {
            var widgetThis = this;
            var $button = widgetThis._element.find(".switch-button-bg + div");
            var $textDiv = $button.find(".tiny-switch-middle");

            if ( !widgetThis.maxWidth ) {                
                var _w = $textDiv.width();
                if(_w==0){
                    var temp=$textDiv.clone();
                    $("body").append(temp);
                    _w=temp.width();
                    temp.remove();
                }
                if ( _w  > 0) {
                    var _w2 = $textDiv.text(widgetThis.options.items[1].label).width();
                    widgetThis.maxWidth = _w > _w2 ? _w : _w2;
                    widgetThis.maxWidth = widgetThis.maxWidth + 2;
                    $textDiv.width(widgetThis.maxWidth);
                    var _bgMiddleWidth = 2 * widgetThis.maxWidth + HEMICYCLE_WIDTH;                    
                    widgetThis._element.find(".switch-button-bg > .tiny-switch-middle").width( _bgMiddleWidth );
                    widgetThis._element.width(2 * HEMICYCLE_WIDTH + _bgMiddleWidth);
                }
                if (widgetThis.options.disable) {
                    widgetThis._setDisable(true);
                }
                if (util.isFalse(widgetThis.options.display)) {
                    widgetThis._setDisplay(false);
                }                
            }

            $textDiv.text(widgetThis.selectedItem.label);
            $button.removeClass();
            if ( widgetThis.options.selected == "on" ) {
                widgetThis._element.find(".switch-button-bg").addClass("switch-bg-focus");
                $button.addClass("switch-button-on");
                $button.css("left", widgetThis.maxWidth+HEMICYCLE_WIDTH);
            } else {
                widgetThis._element.find(".switch-button-bg").removeClass("switch-bg-focus");
                $button.addClass("switch-button-off");
                $button.css("left", 0);                 
            }           
        },

        /**
         * 更新扩展状态切换开关
        */
        _updateExtend : function() {
            var widgetThis = this;
            var $buttons = widgetThis._element.find(".switch-button-bg ~ .switch-button");
            var _maxWidth = 0;
            var $textList = $buttons.find(".tiny-switch-middle");

            if ( !widgetThis.maxWidth ) {
                _.each($textList, function( textDiv ) {                
                    var _w = $(textDiv).width();
                    if ( _w > _maxWidth ) {
                        _maxWidth = _w;
                    }               
                });
                if ( _maxWidth > 0 ) {
                    widgetThis.maxWidth = _maxWidth;
                    widgetThis.maxWidth = widgetThis.maxWidth + 2;
                    $textList.width(widgetThis.maxWidth);
                    var _num = $textList.length;
                    var _bgWidth =  _num * (2*HEMICYCLE_WIDTH + widgetThis.maxWidth) -2*HEMICYCLE_WIDTH;
                    widgetThis._element.find(".switch-button-bg > .tiny-switch-middle").width(_bgWidth);
                    widgetThis._element.width(_bgWidth+2*HEMICYCLE_WIDTH);
                }
                _.each($buttons, function( button, index ) {
                    if (index > 0) {
                        $(button).css("left", index * (widgetThis.maxWidth+2*HEMICYCLE_WIDTH));
                    }
                });
                if (widgetThis.options.disable) {
                    widgetThis._setDisable(true);
                }
                if (util.isFalse(widgetThis.options.display)) {
                    widgetThis._setDisplay(false);
                }                
            }
            widgetThis._element.find(".switch-button-selected").removeClass().addClass("switch-button");
            widgetThis._element.find("div[value="+widgetThis.options.selected+"]").removeClass().addClass("switch-button-selected");
        }

    });
    window.tinyWidget.Switch = Switch;
    return Switch;
});

/**
 * 开关控件
 * @author mark
 * @version 1.0.0
 */

define('tiny-directives/Switch',["tiny-common/util", "tiny-directives/Directive", "tiny-widgets/Switch"], function(util, Directive, SwitchWidget) {
    
    var DEFAULT_CONFIG = {
        directiveName : "tinySwitch",
        widgetClass : SwitchWidget,
        constantProperties : ["id", "display", "disable", "items", "selected", "standard"],
        scope : {
            id : "=",
            display : "=",
            disable : "=",             
            items : "=",
            selected : "=",
            standard : "=",
            change : "&"           
        },
        template : "<div></div>",
        replace : true,
    };

    var Switch = Directive.extend({

        "init" : function(options) {
            var directiveThis = this;
            directiveThis._super(_.extend({}, DEFAULT_CONFIG, options));
        },

        "compile" : function(){
            var directiveThis = this;
            return directiveThis.link;
        },    

        "link": function( scope, element, attrMap ){
            var directiveThis = this, constants = _.pick(scope, directiveThis.constantProperties);           
            var validProperName = [];
            _.filter(constants,function(value,key){
                if(value !== undefined) {
                    validProperName.push(key);
                }
                return value !== undefined;
            });

            var _option = _.pick(constants,validProperName);
            _option.isDirective = true;
            directiveThis = new directiveThis.widgetClass(_option);            
            element.append(directiveThis._element);            
            directiveThis._update();

            scope.$watch("display", function(newValue, oldValue) {
                if (newValue != oldValue) {
                    directiveThis.option("display", newValue);
                }                
            });

            scope.$watch("disable", function(newValue, oldValue) {
                if (newValue != oldValue) {
                    directiveThis.option("disable", newValue);
                }
            });

            scope.$watch("selected", function(newValue, oldValue) {
                if (newValue != oldValue) {
                    directiveThis.option("selected", newValue);
                }
            });

             directiveThis.on("changeEvt", function(param) {
                var canChange = true;                
                if (scope.change) {  
                    var changeFn =  scope.change();
                    if (changeFn) {
                        canChange = changeFn(param);
                    }                          	                    
                }
                if (!util.isFalse(canChange)) {
                    scope.selected = param.newValue;                         
                }
                scope.$apply();
            });            
        }
    });

    new Switch().toAngularDirective();

    return Switch;

});


