                oLang = oSettings.oLanguage,
                iStart = oSettings._iDisplayStart+1,
                iEnd = oSettings.fnDisplayEnd(),
                iMax = oSettings.fnRecordsTotal(),
                iTotal = oSettings.fnRecordsDisplay(),
