            if($.isPlainObject(arguments[0])){
                var rowIndex = _.isObject(arguments[1]) ? arguments[1]._DT_RowIndex : arguments[1];
                widgetThis.dataTableConfig.aaData[rowIndex] = arguments[0];
                widgetThis.getOSettings().aoData[rowIndex]._aData = arguments[0];
            }
            $dataTable.fnUpdate.apply($dataTable,arguments);
            widgetThis.options.data = widgetThis.getTableData();

